{"stdout":"import type { Server } from 'node:http';
import { createServer } from 'node:http';
import { createApp } from '../src/app.ts';
import { NoteStore } from '../src/store.ts';

export interface Harness {
  base: string;
  store: NoteStore;
  lines: string[];
  close: () => Promise<void>;
}

export async function start(store = new NoteStore()): Promise<Harness> {
  const lines: string[] = [];
  const server: Server = createServer(createApp(store, (l: string) => lines.push(l)));
  await new Promise<void>((r) => server.listen(0, '127.0.0.1', r));
  const { port } = server.address() as { port: number };
  return {
    base: `http://127.0.0.1:${port}`,
    store,
    lines,
    close: () => new Promise<void>((r) => { server.close(() => r()); server.closeAllConnections(); }),
  };
}

export const post = (base: string, payload: string, path = '/notes') =>
  fetch(base + path, { method: 'POST', headers: { 'content-type': 'application/json' }, body: payload });
