const p95 = (xs: number[]) => [...xs].sort((a, b) => a - b)[Math.ceil(xs.length * 0.95) - 1];

async function time(fn: () => Promise<Response>, n = 50): Promise<number> {
  const ds: number[] = [];
  for (let i = 0; i < n; i++) {
    const t = performance.now();
    const res = await fn();
    await res.arrayBuffer();
    ds.push(performance.now() - t);
  }
  return p95(ds);
}

