import type { NoteStore } from './store.ts';
import { formatAccessLine } from './logger.ts';
import type { LogSink } from './logger.ts';

function send(res: ServerResponse, status: number, payload: unknown): void {
  const data = JSON.stringify(payload);
  res.writeHead(status, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(data) });
  res.end(data);
}

const fail = (res: ServerResponse, status: number, error: string) => send(res, status, { error });

async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const c of req) chunks.push(c as Buffer);
  return Buffer.concat(chunks).toString('utf8');
}

async function createNote(store: NoteStore, req: IncomingMessage, res: ServerResponse): Promise<void> {
  let data: unknown;
  try {
    data = JSON.parse(await readBody(req));
  } catch {
    return fail(res, 400, 'invalid JSON');
  }
  if (typeof data !== 'object' || data === null || Array.isArray(data)) return fail(res, 400, 'body must be a JSON object');
  const { title, body = '' } = data as Record<string, unknown>;
  if (typeof title !== 'string' || typeof body !== 'string') return fail(res, 400, 'title and body must be strings');
  if (title.trim() === '') return fail(res, 400, 'title must not be empty');
  send(res, 201, store.create(title, body));
}

type Handler = (req: IncomingMessage, res: ServerResponse, param: string) => void | Promise<void>;
type Route = { pattern: RegExp; handlers: Record<string, Handler> };

function safeDecode(raw: string): string {
  try { return decodeURIComponent(raw); } catch { return raw; }
}

function buildRoutes(store: NoteStore): Route[] {
  return [
    { pattern: /^\/health$/, handlers: { GET: (_q, res) => send(res, 200, { status: 'ok' }) } },
    {
      pattern: /^\/notes$/,
      handlers: {
        POST: (req, res) => createNote(store, req, res),
        GET: (_q, res) => send(res, 200, store.list()),
      },
    },
    {
      pattern: /^\/notes\/([^/]+)$/,
      handlers: {
        GET: (_q, res, raw) => {
          const note = store.get(safeDecode(raw));
          if (note) send(res, 200, note); else fail(res, 404, 'note not found');
        },
      },
    },
  ];
}

async function dispatch(routes: Route[], req: IncomingMessage, res: ServerResponse, path: string): Promise<void> {
  for (const { pattern, handlers } of routes) {
    const m = pattern.exec(path);
    if (!m) continue;
    const handler = Object.hasOwn(handlers, req.method ?? '') ? handlers[req.method as string] : undefined;
    if (!handler) return fail(res, 405, 'method not allowed');
    return handler(req, res, m[1]);
  }
  fail(res, 404, 'not found');
}

export function createApp(store: NoteStore, log: LogSink) {
  const routes = buildRoutes(store);
  return (req: IncomingMessage, res: ServerResponse): void => {
    const start = process.hrtime.bigint();
    const path = (req.url ?? '/').split('?')[0];
    res.on('finish', () => {
      const ms = Number(process.hrtime.bigint() - start) / 1e6;
      log(formatAccessLine(req.method ?? '', path, res.statusCode, ms));
    });
    dispatch(routes, req, res, path).catch(() => {
      if (!res.headersSent) fail(res, 500, 'internal error'); else res.end();
    });
  };
}
