const base = process.env.SMOKE_URL ?? 'http://localhost:8080';

function check(cond: boolean, msg: string): void {
  if (!cond) throw new Error(msg);
}

async function call(label: string, path: string, init?: RequestInit): Promise<Response> {
  try {
    return await fetch(`${base}${path}`, init);
  } catch (e) {
    throw new Error(`${label} unreachable: ${e instanceof Error ? e.message : e}`);
  }
}

async function main(): Promise<void> {
  const health = await call('GET /health', '/health');
  check(health.status === 200, `/health returned ${health.status}`);
  check((await health.json()).status === 'ok', '/health body not ok');

  const created = await call('POST /notes', '/notes', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ title: 'smoke', body: 'test' }),
  });
  check(created.status === 201, `POST /notes returned ${created.status}`);
  const note = await created.json();
  check(typeof note.id === 'string' && note.id.length > 0, 'created note has no id');

  const fetched = await call('GET /notes/:id', `/notes/${note.id}`);
  check(fetched.status === 200, `GET /notes/:id returned ${fetched.status}`);
  const got = await fetched.json();
  check(got.id === note.id && got.title === 'smoke', 'fetched note mismatch');
